function validate([times, targetFriend]) {
  if (!Array.isArray(times) || times.length < 2 || times.length > 10000) return 'times needs 2 to 10000 friends.';
  const arrivals = new Set();
  for (const pair of times) {
    if (!Array.isArray(pair) || pair.length !== 2 || !pair.every(Number.isInteger)) return 'Each entry is [arrival, leaving].';
    const [arrival, leaving] = pair;
    if (arrival < 1 || leaving > 100000 || arrival >= leaving) return 'Need 1 <= arrival < leaving <= 100000.';
    if (arrivals.has(arrival)) return 'Arrival times must be distinct.';
    arrivals.add(arrival);
  }
  if (!Number.isInteger(targetFriend) || targetFriend < 0 || targetFriend >= times.length) return 'targetFriend must be a friend index.';
  return null;
}

