function smallestChair(times, targetFriend) {
  const push = (heap, item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (heap[parent][0] <= heap[i][0]) break;
      [heap[parent], heap[i]] = [heap[i], heap[parent]];
      i = parent;
    }
  };
  const pop = (heap) => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
        if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
        if (smallest === i) break;
        [heap[smallest], heap[i]] = [heap[i], heap[smallest]];
        i = smallest;
      }
    }
    return top;
  };

  const order = times.map((_, friend) => friend).sort((a, b) => times[a][0] - times[b][0]);
  const freeChairs = [];
  const occupied = [];
  let nextChair = 0;
  for (const friend of order) {
    const [arrival, leaving] = times[friend];
    while (occupied.length > 0 && occupied[0][0] <= arrival) {
      push(freeChairs, [pop(occupied)[1]]);
    }
    const chair = freeChairs.length > 0 ? pop(freeChairs)[0] : nextChair++;
    if (friend === targetFriend) {
      return chair;
    }
    push(occupied, [leaving, chair]);
  }
  return -1;
}

