function smallestChair(times, targetFriend) {
  // Replay arrivals in time order; chair c is empty when its last sitter left at or before now.
  const guests = times.map(([come, go], who) => ({ come, go, who })).sort((x, y) => x.come - y.come);
  const emptyFrom = [];
  for (const { come, go, who } of guests) {
    let c = 0;
    while (c < emptyFrom.length && emptyFrom[c] > come) c++;
    emptyFrom[c] = go;
    if (who === targetFriend) return c;
  }
  return -1;
}

