function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 2 + Math.floor(rand() * 7);
  const horizon = large ? 99999 : 2 + Math.floor(rand() * 18);
  // Distinct arrival moments drawn from 1..horizon (horizon < 10^5 leaves room to leave later).
  const pool = Array.from({ length: Math.max(horizon, n) }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const longest = large ? (rand() < 0.5 ? 3000 : 30000) : 1 + Math.floor(rand() * 10);
  const times = pool.slice(0, n).map(arrival => {
    const stay = 1 + Math.floor(rand() * longest);
    return [arrival, Math.min(100000, arrival + stay)];
  });
  const targetFriend = Math.floor(rand() * n);
  return [times, targetFriend];
}
